@dataclass(frozen=True)
class _WorkspaceCreateIntent:
    filename: str


@dataclass(frozen=True)
class _WorkspaceExactValueContract:
    """One closed, ordered value-only projection requested for MCP output."""

    fields: tuple[Literal["document_number", "control_marker"], ...]


@dataclass(frozen=True)
class _WorkspaceInboxRequest:
    """One deterministic operation over the configured read-only MCP inbox."""

    operation: Literal["list", "search", "read", "invalid"]
    relative_path: str = ""
    basename: str = ""
    query: str = ""
    reason: str = ""
    expected_sha256: str = ""
    expected_source_sha256: str = ""


@dataclass(frozen=True)
class _WorkspaceInboxResolution:
    """Closed pre-model outcome of one MCP inbox request."""

    attachment: _WorkspaceInboxAttachment | None = None
    answer: str = ""
    tools_used: tuple[str, ...] = ()
    relative_path: str = ""
    sha256: str = ""
    source_sha256: str = ""


_WORKSPACE_INBOX_CUE = re.compile(
    r"(?:\b(?:mcp|workspace)\s*[-_ ]?\s*(?:inbox|инбокс)\b|"
    r"\b(?:inbox|инбокс)\s+(?:mcp|workspace)\b|"
    r"\b(?:подключ[её]нн\w*\s+)?(?:папк|каталог)\w*\s+(?:mcp|workspace)\b)",
    re.IGNORECASE,
)
_WORKSPACE_INBOX_LIST_ACTION = re.compile(
    r"\b(?:покаж|перечисл|вывед|дай|список|содержим)\w*\b[^.!?\n]{0,64}"
    r"\b(?:файл|папк|каталог|объект)\w*\b|"
    r"\b(?:list|show|display)\b[^.!?\n]{0,64}\b(?:files?|directories|entries)\b",
    re.IGNORECASE,
)
_WORKSPACE_INBOX_SEARCH_ACTION = re.compile(
    r"\b(?:найд|поищ|отыщ)\w*\s+(?:файл\w*\s+)?|"
    r"\b(?:find|search|locate)\b\s+(?:for\s+)?(?:a\s+)?(?:file\s+)?",
    re.IGNORECASE,
)
_WORKSPACE_INBOX_READ_ACTION = re.compile(
    r"\b(?:прочит|открой|открыть|посмотр|проанализ|разбер|извлек|перескаж|сравн|"
    r"ответ|скажи|назов|покаж\w*\s+(?:значени|содержим|поле|код))\w*\b|"
    r"\b(?:read|open|inspect|analy[sz]e|extract|summari[sz]e|answer)\b",
    re.IGNORECASE,
)
_WORKSPACE_INBOX_READ_NEGATED = re.compile(
    r"\b(?:не|никогда\s+не)\s+(?:читай|прочит|откры|смотр|ищ|анализир)\w*\b|"
    r"\b(?:do\s+not|don't|don’t|never)\s+(?:read|open|inspect|search|analy[sz]e)\b",
    re.IGNORECASE,
)
_WORKSPACE_RELATIVE_PATH_TOKEN = re.compile(
    r"(?<![\w./\\-])(?P<path>[\w@+(),.\[\]-]+(?:/[\w@+(),.\[\]-]+)+)"
    r"(?![\w./\\-])",
    re.IGNORECASE,
)
_WORKSPACE_QUOTED_DATA = re.compile(r"[«\"'`](?P<data>[^«»\"'`\r\n]{1,1024})[»\"'`]")
_WORKSPACE_INBOX_MAX_LIST_PAGES = 32
_WORKSPACE_INBOX_MAX_READ_PAGES = 32
_WORKSPACE_INBOX_MAX_SOURCE_CHARS = 200_000


def _workspace_inbox_request(message: str) -> _WorkspaceInboxRequest | None:
    """Parse an explicit MCP-inbox operation without granting host-path access.

    The source cue and action must be unquoted current-user speech.  A quoted
    filename/path is admitted only as inert data after that independent
    authority is present.  Once an inbox cue exists, even an invalid request
    owns the route and can never fall back to a similarly named upload.
    """

    original = _classification_text(message)
    actionable = _workspace_create_actionable_text(message)
    if not _WORKSPACE_INBOX_CUE.search(actionable):
        return None
    if (
        _WORKSPACE_CREATE_NEGATED.search(actionable)
        or _WORKSPACE_INBOX_READ_NEGATED.search(actionable)
        or _workspace_create_has_action_cancellation(actionable)
    ):
        return _WorkspaceInboxRequest("invalid", reason="cancelled_or_negated")
    host_surface = re.sub(r"\bhttps?://[^\s\r\n]+", " ", original, flags=re.IGNORECASE)
    if _ATTACHMENT_HOST_PATH_REFERENCE.search(host_surface):
        return _WorkspaceInboxRequest("invalid", reason="host_or_traversal_path")

    candidates: list[str] = []
    for matched in _WORKSPACE_QUOTED_DATA.finditer(original):
        value = str(matched.group("data") or "").strip()
        if "/" in value or _ATTACHMENT_FILENAME_REFERENCE.fullmatch(value):
            candidates.append(value)
    candidates.extend(
        str(matched.group("path") or "").strip()
        for matched in _WORKSPACE_RELATIVE_PATH_TOKEN.finditer(original)
    )
    candidates.extend(
        str(matched.group("filename") or "").strip()
        for matched in _attachment_filename_reference_matches(original)
    )
    targets = list(dict.fromkeys(value for value in candidates if value))
    if len(targets) > 1:
        return _WorkspaceInboxRequest("invalid", reason="multiple_targets")
    target = targets[0] if targets else ""

    if _WORKSPACE_INBOX_LIST_ACTION.search(actionable) and not target:
        return _WorkspaceInboxRequest("list")
    if (
        _WORKSPACE_INBOX_SEARCH_ACTION.search(actionable)
        and target
        and not _WORKSPACE_INBOX_READ_ACTION.search(actionable)
    ):
        # A pure filename-location request returns the deterministic listing;
        # a request to inspect or answer from that file continues to read.
        return _WorkspaceInboxRequest("search", query=target.rsplit("/", 1)[-1])
    if target and _WORKSPACE_INBOX_READ_ACTION.search(actionable):
        candidate = (
            _WorkspaceInboxRequest("read", relative_path=target)
            if "/" in target
            else _WorkspaceInboxRequest("read", basename=target)
        )
        if not _closed_attachment_read_only_request(_workspace_inbox_task_message(original, candidate)):
            return _WorkspaceInboxRequest("invalid", reason="compound_or_unproven_read")
        return candidate
    return _WorkspaceInboxRequest("invalid", reason="unsupported_or_missing_target")


def _safe_workspace_relative_path(value: Any) -> str:
    """Validate the same relative-path language exposed by the MCP wrapper."""

    candidate = str(value or "")
    if not candidate or "\x00" in candidate or "\\" in candidate or candidate.startswith("/"):
        return ""
    parts = candidate.split("/")
    if any(not part or part in {".", ".."} or len(part.encode("utf-8")) > 255 for part in parts):
        return ""
    return "/".join(parts)


def _workspace_filename_identity(value: Any) -> str:
    return unicodedata.normalize("NFC", str(value or "")).casefold()


def _workspace_inbox_task_message(message: str, request: _WorkspaceInboxRequest) -> str:
    """Remove the already resolved source locator from the content question."""

    visible = _classification_text(message)
    chars = list(visible)
    for matched in _WORKSPACE_INBOX_CUE.finditer(visible):
        chars[matched.start() : matched.end()] = " " * (matched.end() - matched.start())
    target = request.relative_path or request.basename
    if target:
        folded_target = target.casefold()
        folded_visible = visible.casefold()
        cursor = 0
        while (position := folded_visible.find(folded_target, cursor)) >= 0:
            chars[position : position + len(target)] = " " * len(target)
            cursor = position + len(target)
    projected = " ".join("".join(chars).split()).strip(" ,:;—-")
    return projected or "Прочитай выбранный файл."


@dataclass(frozen=True)
class _DirectExactFileFieldContract:
    """Closed ordered attachment fields eligible for verifier bypass."""

    fields: tuple[
        Literal["classification", "document_number", "document_date", "signatory"],
        ...,
    ]


_WORKSPACE_CREATE_SUCCESS_EVIDENCE_PREFIX = "workspace-create-success-v1:"


def _workspace_create_actionable_text(message: str) -> str:
    """Project current user prose while keeping quoted/code examples inert."""

    candidate = str(message or "")
    for pattern in (_VISIBLE_MD_CODE_BLOCK, _VISIBLE_MD_CODE_SPAN, _QUOTED_TEXT):
        candidate = pattern.sub(lambda match: " " * len(match.group(0)), candidate)
    # An unmatched Markdown delimiter is still rendered as code-like user
    # data by common clients.  Conservatively close the affected line/remaining
    # fence instead of normalising its contents into mutation authority.
    if "```" in candidate:
        start = candidate.find("```")
        candidate = candidate[:start] + " " * (len(candidate) - start)
    if "`" in candidate:
        candidate = "\n".join(" " * len(line) if "`" in line else line for line in candidate.split("\n"))
    return " ".join(_classification_text(candidate).split())


def _workspace_create_channel_mentioned(message: str) -> bool:
    """Whether the visible turn contains the exact channel name, even as data."""

    visible = _classification_text(message)
    return bool(
        re.search(r"\bworkspace_create\b", visible, re.IGNORECASE)
        or _WORKSPACE_CREATE_OUTBOX_CUE.search(visible)
    )


def _workspace_create_has_action_cancellation(actionable: str) -> bool:
    """Deny a nearby or contrast-tail cancellation of the requested effect."""

    tokens = re.findall(r"[A-Za-zА-ЯЁа-яё_]+(?:['’][A-Za-z]+)?", actionable.casefold())

    def is_action(token: str) -> bool:
        return token.startswith(("использ", "созда", "запис", "сохран")) or token in {
            "use",
            "create",
            "creating",
            "write",
            "writing",
            "save",
            "saving",
        }

    def is_cancel(token: str) -> bool:
        return token in {
            "не",
            "нет",
            "нельзя",
            "not",
            "never",
            "no",
            "don't",
            "don’t",
            "cannot",
            "can't",
            "can’t",
        } or token.startswith(("отмен", "воздерж", "избег", "cancel", "refrain", "avoid"))

    action_indices = [index for index, token in enumerate(tokens) if is_action(token)]
    cancel_indices = [index for index, token in enumerate(tokens) if is_cancel(token)]
    if any(abs(action - cancel) <= 8 for action in action_indices for cancel in cancel_indices):
        return True

    # A contrast tail can cancel the whole preceding imperative with an
    # anaphora (``но не делай этого`` / ``but don't do it``), so it need not
    # repeat create/write.  Keep it inside one punctuation-bounded sentence.
    for segment in re.split(r"[!?;\n]+|(?<=\.)\s+", actionable.casefold()):
        segment_tokens = re.findall(r"[a-zа-яё_]+(?:['’][a-z]+)?", segment)
        contrast = next(
            (
                index
                for index, token in enumerate(segment_tokens)
                if token in {"но", "однако", "but", "however"}
            ),
            -1,
        )
        if (
            contrast > 0
            and any(is_action(token) for token in segment_tokens[:contrast])
            and any(is_cancel(token) for token in segment_tokens[contrast + 1 :])
        ):
            return True
    return False


def _workspace_create_authorized_clause(actionable: str) -> str:
    """Return one sentence-local imperative for the external outbox.

    A benign lead sentence (for example a request/correlation label) must not
    hide the following command.  Conversely, mentioning ``workspace_create``
    in one sentence cannot authorise an unrelated file imperative in another.
    Quote and code spans have already been blanked by
    :func:`_workspace_create_actionable_text`.
    """

    for raw_clause in re.split(r"(?<=[.!?])\s+", actionable):
        clause = raw_clause.strip()
        if not clause or not _WORKSPACE_CREATE_IMPERATIVE.match(clause):
            continue
        if _WORKSPACE_CREATE_IDENTIFIER_DIRECTIVE.match(clause) or _WORKSPACE_CREATE_OUTBOX_CUE.search(
            clause
        ):
            return clause
    return ""


def _workspace_create_success_evidence(filename: str) -> str:
    return _WORKSPACE_CREATE_SUCCESS_EVIDENCE_PREFIX + json.dumps(
        {"filename": str(filename or "")},
        ensure_ascii=False,
        separators=(",", ":"),
        sort_keys=True,
    )


def _confirmed_workspace_create_filename(
    message: str,
    evidence: object,
) -> str:
    """Bind one successful kernel effect to the exact current-user filename."""

    intent = _explicit_workspace_create_intent(message)
    if intent is None or not isinstance(evidence, list):
        return ""
    expected = _workspace_create_success_evidence(intent.filename)
    return (
        intent.filename
        if any(
            isinstance(item, Mapping)
            and str(item.get("tool") or "") == "workspace_create"
            and str(item.get("output") or "") == expected
            for item in evidence
        )
        else ""
    )


def _workspace_create_channel_request(message: str) -> bool:
    """Recognise one explicit imperative for the external MCP text outbox.

    This is an effect-authority classifier, not a broad semantic intent.  It
    deliberately ignores quoted text and requires either a direct instruction
    to use the exact tool identifier or an imperative naming the MCP outbox.
    """

    actionable = _workspace_create_actionable_text(message)
    if (
        not actionable
        or _WORKSPACE_CREATE_NEGATED.search(actionable)
        or _workspace_create_has_action_cancellation(actionable)
    ):
        return False
    if _WORKSPACE_CREATE_META.search(actionable) or _WORKSPACE_CREATE_DATA_MENTION.search(actionable):
        return False
    return bool(_workspace_create_authorized_clause(actionable))


def _explicit_workspace_create_intent(message: str) -> _WorkspaceCreateIntent | None:
    """Return the one code-owned safe output name for an explicit MCP write."""

    if not _workspace_create_channel_request(message):
        return None
    actionable = _workspace_create_actionable_text(message)
    matches = _attachment_filename_reference_matches(actionable)
    if len(matches) != 1:
        return None
    filename = str(matches[0].group("filename") or "").strip()
    if (
        not filename
        or len(filename) > 255
        or len(filename.encode("utf-8")) > 255
        or "/" in filename
        or "\\" in filename
    ):
        return None
    dot = filename.rfind(".")
    if dot <= 0 or filename[dot:].casefold() not in _WORKSPACE_CREATE_TEXT_SUFFIXES:
        return None
    return _WorkspaceCreateIntent(filename=filename)


def _workspace_exact_value_contract_requested(message: str) -> bool:
    """Whether the visible command claims a closed value-only line contract."""

    actionable = _workspace_create_actionable_text(message)
    return bool(
        _WORKSPACE_EXACT_VALUE_CUE.search(actionable) and _WORKSPACE_OUTPUT_LINE_PREFIX.search(actionable)
    )


def _workspace_exact_value_contract(message: str) -> _WorkspaceExactValueContract | None:
    """Parse the small closed line contract used by exact MCP projections.

    Unknown fields, missing ordinals and unparsed line clauses fail closed.  A
    free-form workspace request returns ``None`` and keeps the ordinary model-
    authored content path.
    """

    actionable = _workspace_create_actionable_text(message)
    if not _workspace_exact_value_contract_requested(actionable):
        return None
    if not _WORKSPACE_NO_OTHER_LINES.search(actionable):
        return None
    requirements: dict[int, Literal["document_number", "control_marker"]] = {}
    for matched in _WORKSPACE_EXACT_VALUE_LINE.finditer(actionable):
        ordinal = str(matched.group("ordinal") or "").casefold()
        ordinal_index = next(
            (value for prefix, value in _ATTACHMENT_ORDINAL_PREFIXES if ordinal.startswith(prefix)),
            -1,
        )
        raw_field = " ".join(str(matched.group("field") or "").casefold().split())
        field: Literal["document_number", "control_marker"]
        if raw_field in {"номера документа", "document number"}:
            field = "document_number"
        elif raw_field in {"контрольного маркера", "control marker"}:
            field = "control_marker"
        else:  # pragma: no cover - regex keeps the mapping closed
            return None
        if ordinal_index < 0 or ordinal_index in requirements or field in requirements.values():
            return None
        requirements[ordinal_index] = field
    if not requirements or sorted(requirements) != list(range(len(requirements))):
        return None
    # Every output-line prefix must have crossed the closed field parser.  This
    # prevents one recognised line from legitimising an extra free-form line.
    if len(list(_WORKSPACE_OUTPUT_LINE_PREFIX.finditer(actionable))) != len(requirements):
        return None
    return _WorkspaceExactValueContract(
        fields=tuple(requirements[index] for index in range(len(requirements)))
    )


def _is_workspace_exact_two_field_contract(
    contract: _WorkspaceExactValueContract | None,
) -> bool:
    """Accept the closed pair in either user-requested output order."""

    return bool(
        contract is not None
        and len(contract.fields) == 2
        and set(contract.fields) == {"document_number", "control_marker"}
    )


def _direct_exact_file_field_contract(message: str) -> _DirectExactFileFieldContract | None:
    """Recognise the one ordered field projection with deterministic evidence."""

    if _requested_exact_file_body_count(message) != 4:
        return None
    fields: list[Literal["classification", "document_number", "document_date", "signatory"]] = []
    for matched in _DIRECT_EXACT_FILE_FIELD.finditer(_classification_text(message)):
        if matched.group("classification"):
            fields.append("classification")
        elif matched.group("number"):
            fields.append("document_number")
        elif matched.group("date"):
            fields.append("document_date")
        elif matched.group("signatory"):
            fields.append("signatory")
    expected: tuple[
        Literal["classification", "document_number", "document_date", "signatory"],
        ...,
    ] = ("classification", "document_number", "document_date", "signatory")
    if tuple(fields) != expected:
        return None
    return _DirectExactFileFieldContract(fields=expected)


def _workspace_reply_attachment_selector_message(message: str) -> str:
    """Project selectors without treating output-line wording as a file pointer.

    This projection is used only after the runtime has proved one exact,
    authorised structural reply attachment and one explicit ``workspace_create``
    output.  Ordinals in clauses such as ``Первая строка — номер документа``
    describe the future output, not another document in the archive.  Genuine
    input selectors outside those line clauses (for example ``по второму
    документу``) remain intact.
    """

    projected = _attachment_selector_message(message)
    chars = list(projected)
    for match in _WORKSPACE_OUTPUT_LINE_PREFIX.finditer(projected):
        chars[match.start() : match.end()] = " " * (match.end() - match.start())
    return "".join(chars)


def _attachment_count_range_side(message: str) -> str:
    """`first N` / `last N` on unquoted speech, ignoring filename text."""

    surface = _record_source_command_text(message)
    chars = list(surface)
    for matcher in (_ATTACHMENT_QUOTED_FILENAME_REFERENCE, _ATTACHMENT_BARE_FILENAME_REFERENCE):
        for match in matcher.finditer(surface):
            chars[match.start() : match.end()] = " " * (match.end() - match.start())
    folded = _normalized_attachment_selector("".join(chars))
    if re.search(r"\b(?:перв|first)\w*\b", folded):
        return "first"
    if re.search(r"\b(?:последн|last|recent)\w*\b", folded):
        return "last"
    return ""


def _attachment_requested_catalog_indices(
    message: str,
    *,
    total: int,
    current_supplied: bool = False,
) -> tuple[tuple[int, ...], int]:
    """Resolve bounded file ordinals against stable upload chronology."""

    surface = _record_source_command_text(message)
    selector_chars = list(surface)
    for matcher in (_ATTACHMENT_QUOTED_FILENAME_REFERENCE, _ATTACHMENT_BARE_FILENAME_REFERENCE):
        for match in matcher.finditer(surface):
            selector_chars[match.start() : match.end()] = " " * (match.end() - match.start())
    selector_text = "".join(selector_chars)
    if total <= 0:
        requested = (
            sum(
                1
                for phrase in _ATTACHMENT_NUMERIC_ORDINAL_LIST.finditer(selector_text)
                for _ordinal in _ATTACHMENT_NUMERIC_ORDINAL_TOKEN.finditer(phrase.group(0))
            )
            + len(tuple(_ATTACHMENT_NOUN_NUMERIC_ORDINAL.finditer(selector_text)))
            + sum(
                1
                for phrase in _ATTACHMENT_WORD_ORDINAL_PHRASE.finditer(selector_text)
                for _ordinal in _ATTACHMENT_ORDINAL_TOKEN.finditer(phrase.group(0))
            )
        )
        return (), requested
    folded = _normalized_attachment_selector(selector_text)
    indices: list[int] = []
    invalid = 0

    def add(index: int) -> None:
        nonlocal invalid
        if 0 <= index < total and index not in indices:
            indices.append(index)
        elif not 0 <= index < total:
            invalid += 1

    for phrase in _ATTACHMENT_NUMERIC_ORDINAL_LIST.finditer(folded):
        for match in _ATTACHMENT_NUMERIC_ORDINAL_TOKEN.finditer(phrase.group(0)):
            try:
                add(int(match.group("number")) - 1)
            except ValueError:  # pragma: no cover - regex emits digits only
                continue
    for phrase in _ATTACHMENT_NOUN_NUMERIC_ORDINAL.finditer(folded):
        for match in re.finditer(r"\d{1,3}", phrase.group(0)):
            try:
                add(int(match.group(0)) - 1)
            except ValueError:  # pragma: no cover - regex emits digits only
                continue
    for phrase in _ATTACHMENT_WORD_ORDINAL_PHRASE.finditer(folded):
        for match in _ATTACHMENT_ORDINAL_TOKEN.finditer(phrase.group(0)):
            token = match.group(0)
            if token.startswith(("предпослед", "penultimate")):
                add(total - 2)
                continue
            if token.startswith(("предыдущ", "previous")):
                add(total - 1 if current_supplied else total - 2)
                continue
            if token.startswith(("послед", "last")):
                add(total - 1)
                continue
            for prefix, index in _ATTACHMENT_ORDINAL_PREFIXES:
                if token.startswith(prefix):
                    add(index)
                    break
    return tuple(indices), invalid


def _attachment_reference_terms(message: str) -> tuple[str, ...]:
    """Content clues for an indirect file selector, never general retrieval."""

    folded = _normalized_attachment_selector(message)
    quoted = [
        _normalized_attachment_selector(match.group(0)[1:-1])
        for match in _QUOTED_TEXT.finditer(folded)
        if len(_normalized_attachment_selector(match.group(0)[1:-1])) >= 3
    ]
    words: list[str] = []
    for match in re.finditer(r"[\w@.+/-]{3,}", folded):
        token = match.group(0).strip("._-/+")
        if (
            len(token) < 3
            or token in _ATTACHMENT_REFERENCE_STOP_WORDS
            or token.isdigit()
            or any(token.startswith(prefix) for prefix in _ATTACHMENT_REFERENCE_STOP_PREFIXES)
        ):
            continue
        words.append(token)
    return tuple(dict.fromkeys([*quoted, *words]))[:12]


def _unquoted_topic_continuation_cue(message: str) -> bool:
    """Independent unquoted continuation or source cue for topic restoration."""

    text = _record_source_command_text(message)
    return bool(
        text
        and (
            _DEICTIC_SAME_FILE_TOPIC.search(text)
            or _DEICTIC_CURRENT_ATTACHMENT_REFERENCE.search(text)
            or _DEICTIC_ATTACHMENT_CONTINUATION.search(text)
            or _ATTACHMENT_LAST_ITEM_REQUEST.search(text)
            or _EXPLICIT_ATTACHMENT_REFERENCE.search(text)
            or _file_route_action_command(message)
            or _independent_source_set_request(message)
        )
    )


def _attachment_topic_terms(message: str) -> tuple[str, ...]:
    """Meaningful morphological hints for one positive active-file continuation."""

    include_quoted = _unquoted_topic_continuation_cue(message)
    surface = _classification_text(message) if include_quoted else _record_source_command_text(message)
    folded = _normalized_attachment_selector(surface)
    terms: list[str] = []
    for matched in re.finditer(r"[^\W_]{5,}", folded):
        token = matched.group(0)
        if token in _ATTACHMENT_TOPIC_STOP_WORDS or any(
            token.startswith(prefix) for prefix in _ATTACHMENT_TOPIC_STOP_PREFIXES
        ):
            continue
        normalized = stem(token, min_input=5).casefold().replace("ё", "е")
        if len(normalized) >= 5 and normalized not in terms:
            terms.append(normalized)
        if len(terms) >= 8:
            break
    return tuple(terms)


def _attachment_topic_matches_source(message: str, source: str) -> bool:
    """Strong positive overlap: one long name or two independent terms."""

    terms = _attachment_topic_terms(message)
    if not terms:
        return False
    folded_source = _normalized_attachment_selector(source)[:500_000]
    matched: list[str] = []
    for term in terms:
        if re.search(rf"(?<!\w){re.escape(term)}[^\W_]*", folded_source):
            matched.append(term)
    return bool(any(len(term) >= 8 for term in matched) or len(matched) >= 2)


def _filename_match_parts(value: str) -> tuple[str, str, tuple[str, ...], str]:
    """A bounded Unicode filename signature, separate from body retrieval."""

    normalized = _normalized_attachment_selector(value)[:260]
    stem, extension = normalized, ""
    if "." in normalized:
        possible_stem, possible_extension = normalized.rsplit(".", 1)
        if re.fullmatch(r"[a-z0-9]{1,16}", possible_extension, flags=re.IGNORECASE):
            stem, extension = possible_stem, possible_extension
    tokens = tuple(re.findall(r"[^\W_]+", stem))[:32]
    compact = "".join(tokens)[:260]
    return stem, extension, tokens, compact


def _fuzzy_filename_score(requested: str, candidate: str) -> float:
    """Similarity for an explicit filename only; never inspect file content."""

    requested_stem, requested_extension, requested_tokens, requested_compact = _filename_match_parts(
        requested
    )
    candidate_stem, candidate_extension, candidate_tokens, candidate_compact = _filename_match_parts(
        candidate
    )
    if not requested_compact or not candidate_compact:
        return 0.0
    if requested_extension and candidate_extension != requested_extension:
        return 0.0
    if requested_stem == candidate_stem:
        return 1.0
    if requested_compact == candidate_compact:
        return 0.99

    sequence = SequenceMatcher(
        None,
        requested_compact,
        candidate_compact,
        autojunk=False,
    ).ratio()
    requested_set = set(requested_tokens)
    candidate_set = set(candidate_tokens)
    token_union = requested_set | candidate_set
    token_overlap = len(requested_set & candidate_set) / len(token_union) if token_union else 0.0
    score = max(sequence, sequence * 0.78 + token_overlap * 0.22)
    shortest = min(len(requested_compact), len(candidate_compact))
    threshold = 0.92 if shortest < 6 else 0.86 if shortest < 10 else 0.80
    return score if score >= threshold else 0.0


def _fuzzy_filename_ids(
    requested: str,
    catalog: Sequence[Mapping[str, str]],
) -> tuple[list[str], int]:
    """Return one unambiguous approximate filename or a closed ambiguity."""

    scored: list[tuple[float, str]] = []
    for item in catalog[:_CONVERSATION_ATTACHMENT_ARCHIVE_CATALOG_MAX_FILES]:
        raw_id = str(item.get("raw_object_id") or "")
        filename = str(item.get("filename") or "")
        if not _RAW_OBJECT_ID_RE.fullmatch(raw_id):
            continue
        score = _fuzzy_filename_score(requested, filename)
        if score:
            scored.append((score, raw_id))
    if not scored:
        return [], 0
    best = max(score for score, _raw_id in scored)
    # A small margin is intentionally conservative: two nearly identical names
    # require clarification instead of choosing by upload time or body content.
    winners = list(dict.fromkeys(raw_id for score, raw_id in scored if score >= best - 0.035))
    return (winners, len(winners)) if len(winners) != 1 else (winners, 1)


def _filename_clue_terms(message: str) -> tuple[str, ...]:
    """Pruned descriptive filename terms, separate from file-body clues."""

    result: list[str] = []
    for phrase in _attachment_reference_terms(message):
        for matched in re.finditer(r"[^\W_]{4,}", phrase):
            token = matched.group(0)
            if token in _ATTACHMENT_TOPIC_STOP_WORDS or any(
                token.startswith(prefix) for prefix in _ATTACHMENT_TOPIC_STOP_PREFIXES
            ):
                continue
            normalized = stem(token, min_input=4).casefold().replace("ё", "е")
            if len(normalized) >= 4 and normalized not in result:
                result.append(normalized)
            if len(result) >= 8:
                return tuple(result)
    return tuple(result)


def _filename_clue_match(term: str, token: str) -> float:
    normalized = stem(token, min_input=4).casefold().replace("ё", "е")
    if len(normalized) < 4:
        return 0.0
    if term == normalized:
        return 1.0
    if min(len(term), len(normalized)) >= 4 and (term.startswith(normalized) or normalized.startswith(term)):
        return 0.96
    ratio = SequenceMatcher(None, term, normalized, autojunk=False).ratio()
    return ratio if ratio >= 0.84 else 0.0


def _filename_clue_ids(
    message: str,
    catalog: Sequence[Mapping[str, str]],
    *,
    terms: Sequence[str] | None = None,
    minimum_matches: int | None = None,
) -> tuple[list[str], int]:
    """Rank descriptive terms against filenames before any body search."""

    clue_terms = tuple(dict.fromkeys(terms or _filename_clue_terms(message)))[:8]
    if not clue_terms:
        return [], 0
    scored: list[tuple[float, str]] = []
    for item in catalog[:_CONVERSATION_ATTACHMENT_ARCHIVE_CATALOG_MAX_FILES]:
        raw_id = str(item.get("raw_object_id") or "")
        if not _RAW_OBJECT_ID_RE.fullmatch(raw_id):
            continue
        _stem, _extension, tokens, _compact = _filename_match_parts(str(item.get("filename") or ""))
        matches = [
            max((_filename_clue_match(term, token) for token in tokens), default=0.0) for term in clue_terms
        ]
        positive = [score for score in matches if score > 0]
        long_match = any(
            score > 0 and len(term) >= 8 for term, score in zip(clue_terms, matches, strict=True)
        )
        if minimum_matches is not None:
            if len(positive) < max(1, min(int(minimum_matches), len(clue_terms))):
                continue
        elif not long_match and len(positive) < 2:
            continue
        scored.append((len(positive) + sum(positive) / max(1, len(positive)), raw_id))
    if not scored:
        return [], 0
    best = max(score for score, _raw_id in scored)
    winners = list(dict.fromkeys(raw_id for score, raw_id in scored if score >= best - 0.15))
    return (winners, len(winners)) if len(winners) != 1 else (winners, 1)


def _descriptive_filename_selector(message: str) -> bool:
    """Whether an explicit file phrase carries a plausible filename clue."""

    command = _record_source_command_text(message)
    visible = _classification_text(message)
    named_cue = bool(
        _EXPLICIT_DESCRIPTIVE_FILENAME_CUE.search(command)
        or re.search(
            rf"\b{_ATTACHMENT_REFERENCE_NOUN}\b\s+"
            r"(?:с|со|про|о|об|под\s+названи\w*|именуем\w*|назван\w*)",
            command,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\bв\s+[0-9A-Za-zА-ЯЁа-яё_.-]{4,80}\s+"
            r"(?:посмотр\w*|проверь\w*|поищ\w*|найд\w*)\b",
            command,
            flags=re.IGNORECASE,
        )
    )
    quoted_prior_name_cue = bool(
        re.search(
            rf"\b(?:ранее\s+)?(?:загружен|прислан|отправлен)\w*\s+"
            rf"{_ATTACHMENT_REFERENCE_NOUN}\b\s*[«\"]",
            visible,
            flags=re.IGNORECASE,
        )
    )
    # A generic carrier such as ``из загруженного документа`` identifies the
    # conversation attachment; the neighbouring web/topic words are not its
    # filename.  Descriptive lookup needs its own positive naming grammar.
    return bool((named_cue or quoted_prior_name_cue) and _filename_clue_terms(message))


_EXPLICIT_DESCRIPTIVE_FILENAME_CUE = re.compile(
    rf"(?:"
    rf"\b{_ATTACHMENT_REFERENCE_NOUN}\b\s+"
    r"(?:с|со|про|о|об|под\s+названи\w*|именуем\w*|назван\w*)\s+\S|"
    r"\b(?:file|document|attachment)\b\s+"
    r"(?:with|about|named|called|titled)\s+\S"
    r")",
    re.IGNORECASE,
)


@dataclass(frozen=True)
class _FilenameInventoryRequest:
    term: str


@dataclass(frozen=True)
class _FilenameClueRequest:
    """A closed, unquoted request to discover one prior upload by its filename."""

    terms: tuple[str, ...]
    minimum_matches: int
    display_clue: str


@dataclass(frozen=True)
class _FilenameClueSelection:
    """Body-free candidate verdict followed, at most, by one exact re-read."""

    applies: bool = False
    attachments: tuple[dict[str, Any], ...] = ()
    expected_count: int = 0
    answer: str = ""


_FILENAME_INVENTORY_ACTION = re.compile(
    r"\b(?:есть|найд\w*|покаж\w*|перечисл\w*|какие|сколько|проверь\w*)\b",
    re.IGNORECASE,
)
_FILENAME_INVENTORY_SCOPE = re.compile(
    r"\b(?:файл|документ|вложен)\w*[^.!?\n]{0,100}"
    r"\b(?:в\s+названи\w*|в\s+имени|названи\w*)\b",
    re.IGNORECASE,
)

_FILENAME_CLUE_TOKEN = r"[0-9A-Za-zА-ЯЁа-яё][0-9A-Za-zА-ЯЁа-яё_.-]{3,39}"
_NATURAL_FILENAME_CLUE = re.compile(
    rf"\bв\s+(?P<clue>{_FILENAME_CLUE_TOKEN})\s+"
    r"(?:посмотр\w*|поищ\w*|провер\w*|найд\w*)\b",
    re.IGNORECASE,
)
_PRIOR_UPLOAD_FILENAME_CUE = re.compile(
    r"(?:"
    r"\b(?:я\s+)?(?:уже\s+|раньше\s+)?"
    r"(?:кидал|скидывал|присылал|отправлял|загружал)\w*\b|"
    r"\b(?:кидал|скидывал|присылал|отправлял|загружал)\w*"
    r"(?:\s+\w+){0,3}\s+(?:уже|раньше)\b"
    r")",
    re.IGNORECASE,
)
_APPROX_FILENAME_PAIR_THERE = re.compile(
    rf"\b(?P<first>{_FILENAME_CLUE_TOKEN})\s+(?P<second>{_FILENAME_CLUE_TOKEN})"
    r"\s*[,;:–—-]?\s*(?:(?:он|она|оно|они)\s+)?там\s+"
    r"(?:есть|указан\w*|упомянут\w*|написан\w*)\b",
    re.IGNORECASE,
)
_APPROX_FILENAME_PAIR_ACTION = re.compile(
    rf"(?:"
    rf"\b(?:в|из)\s+(?P<source_first>{_FILENAME_CLUE_TOKEN})\s+"
    rf"(?P<source_second>{_FILENAME_CLUE_TOKEN})\s+"
    r"(?:посмотр\w*|поищ\w*|провер\w*|найд\w*)\b|"
    r"\b(?:посмотр\w*|поищ\w*|провер\w*|найд\w*)\s+"
    rf"(?:в|из)\s+(?P<action_first>{_FILENAME_CLUE_TOKEN})\s+"
    rf"(?P<action_second>{_FILENAME_CLUE_TOKEN})\b"
    r")",
    re.IGNORECASE,
)


def _filename_clue_is_web_scope(value: str) -> bool:
    """A web location is an action scope, never a prior filename clue."""

    normalized = stem(value, min_input=4).casefold().replace("ё", "е")
    return normalized in {"интернет", "сет", "онлайн", "online", "web", "сайте", "сайт"}


def _filename_clue_request(message: str) -> _FilenameClueRequest | None:
    """Recognise two bounded body-free filename discovery forms.

    All authority comes from current speech.  Quoted examples cannot select a
    file, and query literals are never promoted into filename clues.
    """

    command = _record_source_command_text(message)
    if not command:
        return None

    natural = _NATURAL_FILENAME_CLUE.search(command)
    if natural is not None and _PRIOR_UPLOAD_FILENAME_CUE.search(command):
        raw_clue = str(natural.group("clue") or "").strip()
        if _filename_clue_is_web_scope(raw_clue):
            return None
        terms = _filename_clue_terms(raw_clue)
        if len(terms) == 1:
            return _FilenameClueRequest(terms=terms, minimum_matches=1, display_clue=raw_clue)

    pair = _APPROX_FILENAME_PAIR_THERE.search(command) or _APPROX_FILENAME_PAIR_ACTION.search(command)
    if pair is None:
        return None
    groups = pair.groupdict()
    first = str(groups.get("first") or groups.get("source_first") or groups.get("action_first") or "")
    second = str(groups.get("second") or groups.get("source_second") or groups.get("action_second") or "")
    # ``найди в интернете свежие новости`` has the same shallow shape as
    # ``найди в БПЛА штат``.  A web location is an action scope, never a
    # descriptive filename.  Close it before catalog lookup so an otherwise
    # valid file+web continuation can restore its real attachment lineage.
    if _filename_clue_is_web_scope(first):
        return None
    terms = _filename_clue_terms(f"{first} {second}")
    if len(terms) != 2 or terms[0] == terms[1]:
        return None
    return _FilenameClueRequest(
        terms=terms,
        minimum_matches=2,
        display_clue=f"{first} {second}".strip(),
    )


def _filename_inventory_request(message: str) -> _FilenameInventoryRequest | None:
    """Parse a body-free filename substring inventory request."""

    command = _record_source_command_text(message)
    if not (_FILENAME_INVENTORY_ACTION.search(command) and _FILENAME_INVENTORY_SCOPE.search(command)):
        return None
    quoted = [
        match.group(0)[1:-1].strip()
        for match in _QUOTED_TEXT.finditer(_classification_text(message))
        if 2 <= len(match.group(0)[1:-1].strip()) <= 80
    ]
    if len(quoted) == 1:
        term = quoted[0]
    elif quoted:
        return None
    else:
        matched = re.search(
            r"\b(?:слово|фраз[ау]|подстрок[ау])\s+"
            r"(?P<term>[0-9A-Za-zА-ЯЁа-яё_.-]{2,80})\b",
            command,
            re.IGNORECASE,
        )
        if matched is None:
            return None
        term = str(matched.group("term") or "").strip()
    normalized = _normalized_attachment_selector(term)
    if not normalized or len(normalized) > 80:
        return None
    return _FilenameInventoryRequest(term=term)


def _raw_file_is_audio(content_type: str, metadata: Mapping[str, Any]) -> bool:
    raw_kind = str(content_type or "").strip().casefold()
    media_kind = str(metadata.get("media_kind") or "").strip().casefold()
    mime = (
        str(metadata.get("mime_type") or metadata.get("mime") or metadata.get("content_type") or "")
        .strip()
        .casefold()
    )
    filename = str(metadata.get("filename") or "").strip().casefold()
    return bool(
        raw_kind in {"audio", "voice"}
        or raw_kind.startswith(("audio/", "voice/"))
        or media_kind in {"audio", "voice"}
        or mime.startswith("audio/")
        or filename.endswith(_ATTACHMENT_AUDIO_SUFFIXES)
    )


def _requires_complete_attachment_evidence(question: str, answer: str) -> bool:
    """Whether passing the answer requires coverage of the whole attachment."""

    question_text = str(question or "")
    answer_text = str(answer or "")
    question_command = _record_source_command_text(question_text)
    question_is_explicitly_partial = _attachment_explicitly_partial_scope(question_text)
    answer_is_explicitly_partial = bool(_ANSWER_EXPLICITLY_PARTIAL_ATTACHMENT.search(answer_text))
    return bool(
        _REQUIRES_COMPLETE_ATTACHMENT_EVIDENCE.search(question_command)
        or _ATTACHMENT_RECORD_POSITION.search(question_command)
        or _attachment_whole_document_task(question_text, file_count=2)
        or (_ATTACHMENT_SUMMARY_REQUEST.search(question_command) and not question_is_explicitly_partial)
        or (
            not answer_is_explicitly_partial
            and (
                _REQUIRES_COMPLETE_ATTACHMENT_EVIDENCE.search(answer_text)
                or _ANSWER_CLAIMS_COMPLETE_ATTACHMENT.search(answer_text)
            )
        )
    )


def _answer_claims_complete_attachment(answer: str) -> bool:
    """Narrow answer-side postcondition; schema summaries are not whole-set claims."""

    text = str(answer or "")
    if _ANSWER_EXPLICITLY_PARTIAL_ATTACHMENT.search(text):
        return False
    return bool(
        _ANSWER_CLAIMS_COMPLETE_ATTACHMENT.search(text) or _ANSWER_NAMES_ALL_ATTACHMENT_MEMBERS.search(text)
    )


def _attachment_evidence_chunks(
    attachments: list[dict[str, Any]] | None,
) -> list[dict[str, str]]:
    """Ephemeral, evenly bounded evidence for verifier and one repair pass.

    The chunks mirror only text which was already shown to the synthesis model.
    They are returned in the existing tool-evidence shape for reuse by the
    verifier, but callers must not attach them to ``response`` or persist them.
    """

    projected = _bounded_attachment_projection(attachments)
    office_prompt = next(
        (
            str(item.get("_office_prompt_serialized") or "")
            for item in projected
            if str(item.get("_office_prompt_serialized") or "")
        ),
        "",
    )
    chunks: list[dict[str, str]] = [{"tool": "attachment", "output": office_prompt}] if office_prompt else []
    candidates = [
        item
        for item in projected
        if item.get("_office_structured") is not True
        if (str(item.get("transient_text") or "").strip() or item.get("empty_text") is True)
        and item.get("verification_eligible", True) is not False
    ]
    if not candidates:
        return chunks
    for item in candidates:
        filename = str(item.get("filename") or item.get("name") or "attachment")[:260]
        caveat = _what_is_missing_from_this_attachment(item)
        text = str(item.get("transient_text") or "")
        if not text and item.get("empty_text") is True:
            if len(chunks) < _ATTACHMENT_EVIDENCE_MAX_CHUNKS:
                chunks.append(
                    {
                        "tool": "attachment",
                        "output": (
                            f"Вложение {json.dumps(filename, ensure_ascii=False)}: "
                            "файл полностью разобран; извлечённый текст пуст."
                        ),
                    }
                )
            continue
        for offset in range(0, len(text), _ATTACHMENT_EVIDENCE_CHUNK_CHARS):
            if len(chunks) >= _ATTACHMENT_EVIDENCE_MAX_CHUNKS:
                break
            file_chunk_index = offset // _ATTACHMENT_EVIDENCE_CHUNK_CHARS
            body = text[offset : offset + _ATTACHMENT_EVIDENCE_CHUNK_CHARS]
            note = f"; {caveat}" if caveat else ""
            chunks.append(
                {
                    "tool": "attachment",
                    "output": (
                        f"Вложение {json.dumps(filename, ensure_ascii=False)}, "
                        f"фрагмент {file_chunk_index + 1}{note}:\n{body}"
                    ),
                }
            )
    return chunks[:_ATTACHMENT_EVIDENCE_MAX_CHUNKS]


def _split_office_attachment_evidence(
    entries: list[dict[str, str]],
) -> tuple[list[str], list[str]]:
    """Keep canonical Office bytes separate from legacy delimited evidence.

    Office projections are already a closed JSON envelope with their own trust
    label.  Passing them through the legacy XML-delimiter scrubber would mutate
    a perfectly legitimate cell containing ``</untrusted_data>`` and make the
    verifier/repair see different evidence from synthesis.
    """

    office_records: list[str] = []
    legacy_records: list[str] = []
    for entry in entries:
        output = str(entry.get("output") or "")
        if not output.strip():
            continue
        if output.startswith((OFFICE_PROMPT_PREFIX, _ATTACHMENT_MAP_PREFIX)):
            office_records.append(output)
        else:
            legacy_records.append(output)
    return office_records, legacy_records


